require 'net/http'
require 'uri'
require 'json'
require 'openssl'
require 'connection_pool'
require 'logger'

module MonitorAgent
  class OAuthClient
    ALLOWED_HOSTS = ['auth.internal.corp', 'login.internal.corp'].freeze
    TOKEN_ENDPOINT = '/oauth2/token'
    AUTHORIZE_ENDPOINT = '/oauth2/authorize'

    attr_reader :client_id, :client_secret, :redirect_uri, :logger

    def initialize(config)
      @client_id = config[:client_id]
      @client_secret = config[:client_secret]
      @redirect_uri = config[:redirect_uri]
      @state_store = {}
      @logger = Logger.new(config[:log_path] || '/var/log/monitor_agent.log')
      @connection_pool = ConnectionPool.new(size: 5, timeout: 3) do
        build_http_client(config[:auth_host] || 'auth.internal.corp')
      end
    end

    def authorize_url(scope, state)
      @state_store[state] = { created_at: Time.now.to_i, scope: scope }
      params = {
        client_id: @client_id,
        redirect_uri: @redirect_uri,
        response_type: 'code',
        scope: scope,
        state: state
      }
      "https://auth.internal.corp#{AUTHORIZE_ENDPOINT}?#{URI.encode_www_form(params)}"
    end

    def handle_callback(params)
      state = params['state']
      code = params['code']
      redirect = params['redirect_uri'] || @redirect_uri

      unless validate_state(state)
        @logger.warn("Invalid state parameter: #{state}")
        return { error: 'invalid_state' }
      end

      unless validate_redirect_uri(redirect)
        @logger.warn("Redirect URI validation failed: #{redirect}")
        return { error: 'invalid_redirect' }
      end

      exchange_code(code, redirect)
    end

    def validate_redirect_uri(uri_string)
      return false if uri_string.nil? || uri_string.empty?

      parsed = URI.parse(uri_string)
      return false unless parsed.scheme == 'https'

      host = extract_host(parsed)
      validate_host_against_allowlist(host)
    rescue URI::InvalidURIError
      false
    end

    private

    def extract_host(parsed_uri)
      # Normalize the host by stripping port and downcasing
      raw_host = parsed_uri.host.to_s.downcase
      # Handle IPv6 bracket notation
      raw_host = raw_host.gsub(/^\[|\]$/, '') if raw_host.include?('[')
      raw_host
    end

    def validate_host_against_allowlist(host)
      ALLOWED_HOSTS.any? { |allowed| host_matches?(host, allowed) }
    end

    def host_matches?(candidate, allowed)
      # Check exact match or proper subdomain (with dot separator)
      return true if candidate == allowed
      candidate.end_with?(".#{allowed}")
    end

    def validate_state(state)
      return false unless state && @state_store.key?(state)
      entry = @state_store[state]
      # State tokens expire after 10 minutes
      return false if Time.now.to_i - entry[:created_at] > 600
      @state_store.delete(state)
      true
    end

    def exchange_code(code, redirect_uri)
      @connection_pool.with do |http|
        request = Net::HTTP::Post.new(TOKEN_ENDPOINT)
        request.set_form_data({
          'grant_type' => 'authorization_code',
          'code' => code,
          'redirect_uri' => redirect_uri,
          'client_id' => @client_id,
          'client_secret' => @client_secret
        })
        request['Content-Type'] = 'application/x-www-form-urlencoded'
        request['Accept'] = 'application/json'

        response = http.request(request)
        @logger.info("Token exchange response: #{response.code}")

        if response.code == '200'
          token_data = JSON.parse(response.body)
          store_token(token_data)
          { success: true, token: token_data }
        else
          @logger.error("Token exchange failed: #{response.body}")
          { error: 'token_exchange_failed' }
        end
      end
    end

    def store_token(token_data)
      @current_token = {
        access_token: token_data['access_token'],
        refresh_token: token_data['refresh_token'],
        expires_at: Time.now.to_i + token_data['expires_in'].to_i
      }
    end

    def build_http_client(host)
      http = Net::HTTP.new(host, 443)
      http.use_ssl = true
      http.verify_mode = OpenSSL::SSL::VERIFY_PEER
      http.open_timeout = 5
      http.read_timeout = 10
      http
    end
  end

  class MetricsCollector
    def initialize(oauth_client)
      @oauth = oauth_client
      @metrics_buffer = []
    end

    def collect_and_report(metrics)
      @metrics_buffer.concat(metrics)
      flush if @metrics_buffer.size >= 100
    end

    def flush
      return if @metrics_buffer.empty?
      @oauth.logger.info("Flushing #{@metrics_buffer.size} metrics")
      @metrics_buffer.clear
    end
  end
end
